770	template<typename Storage>
771	SnapshotFileInfoPtr KeeperSnapshotManager<Storage>::serializeSnapshotBufferToDisk(nuraft::buffer & buffer, uint64_t up_to_log_idx)
772	{
773	    ReadBufferFromNuraftBuffer reader(buffer);
774	
775	    auto snapshot_file_name = getSnapshotFileName(up_to_log_idx, compress_snapshots_zstd);
776	    auto tmp_snapshot_file_name = "tmp_" + snapshot_file_name;
777	
778	    auto disk = getLatestSnapshotDisk();
779	    LOG_DEBUG(log, "Receiving snapshot {} to {} disk", up_to_log_idx, isLocalDisk(*disk) ? "local" : "remote");
780	
781	    /// Create empty marker: if both tmp_<name> and <name> exist on restart, the snapshot
782	    /// is treated as incomplete and both are removed (see KeeperSnapshotManager constructor).
783	    {
784	        auto buf = disk->writeFile(tmp_snapshot_file_name);
785	        buf->finalize();
786	    }
787	
788	    auto plain_buf = disk->writeFile(snapshot_file_name);
789	    copyData(reader, *plain_buf);
790	
791	    const size_t bytes_written = plain_buf->count();
792	    ProfileEvents::increment(ProfileEvents::KeeperSnapshotWrittenBytes, bytes_written);
793	
794	    plain_buf->finalize();
795	
796	    Stopwatch watch;
797	    plain_buf->sync();
798	    ProfileEvents::increment(ProfileEvents::KeeperSnapshotFileSyncMicroseconds, watch.elapsedMicroseconds());
799	
800	    disk->removeFile(tmp_snapshot_file_name);
801	
802	    auto snapshot_file_info = std::make_shared<SnapshotFileInfo>(snapshot_file_name, disk);
803	    existing_snapshots.emplace(up_to_log_idx, snapshot_file_info);
804	    removeOutdatedSnapshotsIfNeeded();
805	    moveSnapshotsIfNeeded();
806	
807	    return snapshot_file_info;
808	}
