108	std::vector<std::string> MetadataStorageFromPlainObjectStorage::listDirectory(const std::string & path) const
109	{
110	    auto key_prefix = getKeyForPath(object_storage->getCommonKeyPrefix(), path).serialize();
111	
112	    RelativePathsWithMetadata files;
113	    std::string absolute_key = key_prefix;
114	    if (!absolute_key.empty() && !absolute_key.ends_with('/'))
115	        absolute_key += '/';
116	
117	    object_storage->listObjects(absolute_key, files, 0);
118	
119	    std::unordered_set<std::string> result;
120	    for (const auto & elem : files)
121	    {
122	        const auto & p = elem->relative_path;
123	        chassert(p.find(absolute_key) == 0);
124	        const auto child_pos = absolute_key.size();
125	        /// string::npos is ok.
126	        const auto slash_pos = p.find('/', child_pos);
127	        if (slash_pos == std::string::npos)
128	            result.emplace(p.substr(child_pos));
129	        else
130	            result.emplace(p.substr(child_pos, slash_pos - child_pos));
131	    }
132	    return std::vector<std::string>(std::make_move_iterator(result.begin()), std::make_move_iterator(result.end()));
133	}
