135	DirectoryIteratorPtr MetadataStorageFromPlainObjectStorage::iterateDirectory(const std::string & path) const
136	{
137	    /// Required for MergeTree
138	    auto paths = listDirectory(path);
139	
140	    /// Prepend path, since iterateDirectory() includes path, unlike listDirectory()
141	    std::for_each(paths.begin(), paths.end(), [&](auto & child) { child = fs::path(path) / child; });
142	    std::vector<std::filesystem::path> fs_paths(paths.begin(), paths.end());
143	    return std::make_unique<StaticDirectoryIterator>(std::move(fs_paths));
144	}
