163	ObjectMetadataEntryPtr MetadataStorageFromPlainObjectStorage::getObjectMetadataEntryWithCache(const std::string & path) const
164	{
165	    auto object_key = getKeyForPath(object_storage->getCommonKeyPrefix(), path);
166	    auto get = [&] -> ObjectMetadataEntryPtr
167	    {
168	        if (auto metadata = object_storage->tryGetObjectMetadata(object_key.serialize(), /*with_tags=*/ false))
169	            return std::make_shared<ObjectMetadataEntry>(metadata->size_bytes, metadata->last_modified.epochTime());
170	        return nullptr;
171	    };
172	
173	    if (object_metadata_cache)
174	    {
175	        SipHash hash;
176	        hash.update(object_key.serialize());
177	        auto hash128 = hash.get128();
178	        if (auto res = object_metadata_cache->get(hash128))
179	            return res;
180	        if (auto mapped = get())
181	            return object_metadata_cache->getOrSet(hash128, [&] { return mapped; }).first;
182	        return object_metadata_cache->get(hash128);
183	    }
184	    return get();
185	}
